design.css:
/* Slate — the AniZone look (docs/theme-references/anizone.md): slate-800, Figtree, light headings, a rose home square. */

/* Top bar: translucent gray with a blur; the brand is a rose rounded square with a white mark, no wordmark. */
[data-slot="nav.top"] { background: rgba(31, 41, 55, 0.5) !important; backdrop-filter: blur(12px); border-color: rgba(55, 65, 81, 0.4) !important; }
[data-slot="nav.top"] a[data-slot="brand"] { width: 40px; height: 40px; display: grid; place-items: center; border-radius: 8px; background: rgba(244, 63, 94, 0.9); }
[data-slot="nav.top"] [data-part="brand.mark"] { width: 22px !important; height: 22px !important; background: #fff !important; }
[data-slot="nav.top"] [data-slot="brand"]:has([data-part="brand.text"]),
[data-slot="nav.top"] img[alt="izumi"] { display: none; }
[data-slot="nav.top"] > [data-part="nav.item"] { padding: 8px 16px; border-radius: 8px; color: #cbd5e1; font-size: 16px; font-weight: 400; }
[data-slot="nav.top"] > [data-part="nav.item"]:hover { background: #374151; color: #fff; }
[data-slot="nav.top"] > [data-part="nav.item"][data-active] { color: #fff; }
[data-slot="nav.top"] [data-part="search.field"] { height: 42px; border: 1px solid rgba(55, 65, 81, 0.4); border-radius: 999px; background: rgba(15, 23, 42, 0.3); font-size: 15px; }
@media (min-width: 641px) { [data-slot="home"] { padding-top: 24px; } }

/* Headings: 30 px, weight 400, slate-100; centred on phones. */
[data-part="row.title"], [data-part="block.title"] { font-size: 30px; font-weight: 400; color: #f1f5f9; }
@media (max-width: 640px) {
  [data-part="row.title"], [data-part="block.title"] { width: 100%; font-size: 22px; text-align: center; }
}

/* Latest Episodes: 16:9 stills on gray-700 with a drop shadow; the caption below. */
[data-slot="block.latest-episodes"] [data-part="episode.still"] { border-radius: 8px; overflow: hidden; background: #374151; box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.25); }
[data-slot="block.latest-episodes"] [data-part="episode.number"] { top: auto; left: auto; right: 8px; bottom: 8px; padding: 4px 6px; border-radius: 6px; background: rgba(0, 0, 0, 0.7); font-size: 12px; font-weight: 400; }
[data-slot="block.latest-episodes"] [data-part="card.title"] { margin-top: 12px; font-size: 16px; font-weight: 400; color: #fff; }
[data-slot="block.latest-episodes"] [data-part="card.meta"] { font-size: 14px; color: #fff; }

/* Posters. */
[data-part="slate.poster"] { box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.25); }

/* Top Tags: genre chips as 56 px slate-900 cards with a chevron. */
[data-slot="block.genre-chips"] :has(> [data-part="chip"]) { display: grid; gap: 10px; }
[data-slot="block.genre-chips"] [data-part="chip"] {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 56px;
  padding: 0 18px;
  border-radius: 8px;
  background: linear-gradient(90deg, #0f172a, #1e293b);
  color: #f1f5f9;
  font-size: 15px;
  font-weight: 500;
}
[data-slot="block.genre-chips"] [data-part="chip"]::after { content: "›"; font-size: 22px; color: #cbd5e1; }

/* Series page. */
[data-slot="detail"] [data-part="detail.title"] { font-weight: 500; color: #f1f5f9; }
[data-slot="detail"] [data-part="tab"][data-active] { color: #f43f5e; }
[data-slot="detail"] [data-part="tab"][data-active] > span { background: #f43f5e; }
[data-slot="detail"] [data-part="button"][data-variant="primary"] { border-radius: 8px; }
@media (max-width: 640px) {
  [data-slot="block.latest-episodes"] [data-part="card.title"] { font-size: 15px; }
  [data-slot="block.latest-episodes"] [data-part="card.meta"] { font-size: 12px; color: #cbd5e1; }
}
